package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.tenantconfig.domain.TenantConfigDynamicRegistrationPolicyOptions;

class DynamicRegistrationPolicyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dynamic registration policy of tenant config ")
  void test_dynamic_registration_policy_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> DynamicRegistrationPolicyVO.tryFrom("_OPEN_"));
    Assertions.assertEquals(TenantConfigDynamicRegistrationPolicyOptions.OPEN,
        DynamicRegistrationPolicyVO.tryFrom("OPEN").getDynamicRegistrationPolicy().orElse(null));
    Assertions.assertFalse(
        DynamicRegistrationPolicyVO.nullValue().getDynamicRegistrationPolicy().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        DynamicRegistrationPolicyVO.tryFrom(null).getDynamicRegistrationPolicy().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(TenantConfigDynamicRegistrationPolicyOptions.OPEN,
        DynamicRegistrationPolicyVO.from(TenantConfigDynamicRegistrationPolicyOptions.OPEN)
            .getDynamicRegistrationPolicy().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DynamicRegistrationPolicyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + TenantConfigDynamicRegistrationPolicyOptions.OPEN + "]",
        DynamicRegistrationPolicyVO.from(TenantConfigDynamicRegistrationPolicyOptions.OPEN)
            .toString());
  }
}
